package com.bank.flink.ser;

import java.math.BigDecimal;

// A valid POJO: public, public no-arg constructor, fields via getters/setters.
// Flink builds an efficient PojoSerializer that also supports state evolution.
public class GoodTxn {
    private String txnId;
    private String accountId;
    private BigDecimal amount;

    public GoodTxn() { }  // REQUIRED public no-arg constructor

    public GoodTxn(String txnId, String accountId, BigDecimal amount) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.amount = amount;
    }

    public String getTxnId() { return txnId; }
    public void setTxnId(String txnId) { this.txnId = txnId; }
    public String getAccountId() { return accountId; }
    public void setAccountId(String accountId) { this.accountId = accountId; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
}
