package com.bank.flink.ser;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.logging.Logger;

// Models Flink's compile-time type analysis: decides POJO vs Kryo fallback.
class SerializerSelector {
    private static final Logger log = Logger.getLogger(SerializerSelector.class.getName());

    static class Decision {
        final String serializer;       // "PojoSerializer" or "Kryo"
        final boolean stateEvolution;  // whether schema can evolve
        final int relativeSpeed;       // higher is faster (illustrative)

        Decision(String serializer, boolean stateEvolution, int relativeSpeed) {
            this.serializer = serializer;
            this.stateEvolution = stateEvolution;
            this.relativeSpeed = relativeSpeed;
        }
    }

    Decision analyze(Class<?> type) {
        boolean publicClass = Modifier.isPublic(type.getModifiers());
        boolean hasNoArgCtor = hasPublicNoArgConstructor(type);
        boolean fieldsAccessible = allFieldsAccessible(type);

        if (publicClass && hasNoArgCtor && fieldsAccessible) {
            log.info(() -> type.getSimpleName() + " qualifies as POJO -> PojoSerializer");
            return new Decision("PojoSerializer", true, 100);
        }
        log.warning(() -> type.getSimpleName()
                + " is NOT a POJO (publicClass=" + publicClass
                + ", noArgCtor=" + hasNoArgCtor
                + ", fieldsAccessible=" + fieldsAccessible
                + ") -> FALLBACK to Kryo (slower, no state evolution)");
        return new Decision("Kryo", false, 45);
    }

    private boolean hasPublicNoArgConstructor(Class<?> type) {
        for (Constructor<?> c : type.getConstructors()) {
            if (c.getParameterCount() == 0) return true;
        }
        return false;
    }

    private boolean allFieldsAccessible(Class<?> type) {
        for (Field f : type.getDeclaredFields()) {
            if (Modifier.isStatic(f.getModifiers()) || Modifier.isTransient(f.getModifiers())) continue;
            boolean publicField = Modifier.isPublic(f.getModifiers());
            boolean hasGetterSetter = hasGetter(type, f.getName()) && hasSetter(type, f.getName());
            if (!publicField && !hasGetterSetter) return false;
        }
        return true;
    }

    private boolean hasGetter(Class<?> type, String field) {
        String g = "get" + capitalize(field);
        for (Method m : type.getMethods()) {
            if (m.getName().equals(g) && m.getParameterCount() == 0) return true;
        }
        return false;
    }

    private boolean hasSetter(Class<?> type, String field) {
        String s = "set" + capitalize(field);
        for (Method m : type.getMethods()) {
            if (m.getName().equals(s) && m.getParameterCount() == 1) return true;
        }
        return false;
    }

    private String capitalize(String s) {
        return Character.toUpperCase(s.charAt(0)) + s.substring(1);
    }
}
