package com.bank.flink.ser;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SerializationDemo {
    private static final Logger log = Logger.getLogger(SerializationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        SerializerSelector selector = new SerializerSelector();

        SerializerSelector.Decision bad = selector.analyze(BadTxn.class);
        log.info("BadTxn -> " + bad.serializer + ", speed=" + bad.relativeSpeed
                + ", stateEvolution=" + bad.stateEvolution);

        SerializerSelector.Decision good = selector.analyze(GoodTxn.class);
        log.info("GoodTxn -> " + good.serializer + ", speed=" + good.relativeSpeed
                + ", stateEvolution=" + good.stateEvolution);

        if (!bad.stateEvolution) {
            log.severe("Adding a field to BadTxn would FAIL to restore old Kryo state");
        }
        if (good.stateEvolution) {
            log.info("Adding a field to GoodTxn is SAFE: PojoSerializer migrates state");
        }
    }
}

